<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {X,RefreshCw,Calculator,Check,LoaderCircle,Info} from 'lucide-vue-next'
import {api,refresh} from '../api'
import {money,collectionLabels} from '../types'
const props=defineProps<{collection:string;sourceId:string}>();const emit=defineEmits<{close:[];saved:[]}>()
const preview=ref<any>(null),busy=ref(false),error=ref('')
async function load(){busy.value=true;error.value='';try{preview.value=await api('/recalculate/preview',{method:'POST',body:JSON.stringify({sourceCollection:props.collection,sourceId:props.sourceId})})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function apply(){if(!preview.value?.valid)return;busy.value=true;error.value='';try{await api('/recalculate',{method:'POST',body:JSON.stringify({sourceCollection:props.collection,sourceId:props.sourceId,previewToken:preview.value.previewToken})});await refresh();emit('saved')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="overlay centered" @click.self="emit('close')"><section class="modal wide-modal"><header><span class="icon-tile alcohol"><Calculator :size="22"/></span><button class="icon-button" title="关闭" @click="emit('close')"><X :size="20"/></button></header><h2>预览历史记录的变化</h2><p>缺失费用会在确认种类单价且资料足够时自动补全。这里用于主动修正已有记录的单价与规格；确认后，仅更新下方列出的变化。</p><div v-if="busy&&!preview" class="empty-state compact"><LoaderCircle class="spin" :size="25"/><p>正在检查受影响的记录…</p></div><template v-if="preview"><div class="backup-summary"><div><strong>{{preview.count||0}}</strong><span>受影响记录</span></div><div><strong>{{preview.valid?'通过':'待处理'}}</strong><span>数据校验</span></div></div><div v-if="preview.rows?.length" class="table-scroll"><table><thead><tr><th>记录</th><th>原消耗成本</th><th>重算后成本</th><th>单价变化</th></tr></thead><tbody><tr v-for="r in preview.rows" :key="r.id"><td>{{collectionLabels[r.collection]||r.collection}}<small class="muted"> {{String(r.before?.occurredAt||'').slice(0,10)}}</small></td><td>{{money(r.before?.cost)}}</td><td>{{money(r.after?.cost)}}</td><td>{{money(r.before?.snapshotUnitPrice)}} → {{money(r.after?.snapshotUnitPrice)}}</td></tr></tbody></table></div><p v-if="!preview.count" class="hint">没有需要重算的历史记录。</p><p v-for="(e,i) in preview.errors||[]" :key="i" class="error-box">{{typeof e==='string'?e:JSON.stringify(e)}}</p><p class="hint"><Info :size="15"/>{{preview.message||'手动指定的单价与购买关联会保留。其他数据变动后，需要重新预览。'}}</p></template><p v-if="error" class="error-box">{{error}}</p><footer><button class="button secondary" :disabled="busy" @click="load"><RefreshCw :size="15"/>重新预览</button><button class="button primary" :disabled="busy||preview?.valid!==true||!preview?.count" @click="apply"><Check :size="16"/>确认重算</button></footer></section></div></template>
